const paths={eye:'M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',eyeOff:'m3 3 18 18 M10.6 5.1A12 12 0 0 1 12 5c6.5 0 10 7 10 7a17 17 0 0 1-4 4.7 M6.2 6.2A19 19 0 0 0 2 12s3.5 7 10 7a12 12 0 0 0 5.1-1.1 M9.9 9.9a3 3 0 0 0 4.2 4.2'};
export const uiIcon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.eye}"/></svg>`;
export function passwordButton(id){return `<button type="button" class="password-toggle" data-password-toggle="${id}" aria-label="显示密码" aria-pressed="false">${uiIcon('eye')}</button>`;}
export function bindPasswordToggles(){document.addEventListener('click',event=>{const button=event.target.closest('[data-password-toggle]');if(!button)return;const input=document.getElementById(button.dataset.passwordToggle);if(!input)return;const visible=input.type==='password';input.type=visible?'text':'password';button.innerHTML=uiIcon(visible?'eyeOff':'eye');button.setAttribute('aria-pressed',String(visible));button.setAttribute('aria-label',visible?'隐藏密码':'显示密码');});}
